mapper.select:
SELECT summary
FROM bot_conversation_summary
WHERE conversation_id = #{conversationId}

mapper.insert:
INSERT INTO bot_conversation_message (
    conversation_id,
    message_role,
    content
) VALUES (
    #{conversationId},
    #{role},
    #{content}
)

mapper.select:
SELECT id
FROM bot_conversation_message
WHERE conversation_id = #{conversationId}
ORDER BY id DESC
LIMIT 1 OFFSET #{offset}

mapper.delete:
DELETE FROM bot_conversation_message
WHERE conversation_id = #{conversationId}
  AND id < #{cutoffId}

DELETE FROM bot_conversation_message
WHERE conversation_id = #{conversationId}
  AND create_time < #{createdBefore,
      typeHandler=com.weida.bot.wechatilinkbot.persistence.mybatis.InstantTextTypeHandler}

DELETE FROM bot_conversation_summary
WHERE conversation_id = #{conversationId}
  AND updated_at < #{updatedBefore,
      typeHandler=com.weida.bot.wechatilinkbot.persistence.mybatis.InstantTextTypeHandler}
